  cli.print = (s: string) => { output += s; };

  const chars = await executeSteps({
    steps: [{ type: "create", name: "comp", template: "comp.njk", outputPath: "src/{{componentName}}.ts" }],
    variables: { componentName: "Button" },
    outputFolder: multiUseFolder.append("/simple"),
    rootDir: testRoot,
    worktreeRoot: undefined,
    outputsFolder: multiUseFolder,
    isDryRun: true,
    isOverwrite: false,
    changedFiles: [],
  });

  cli.print = originalPrint;
  assert(chars > 0);
  assert(output.includes("Button"));
  await testRoot.remove();
});

